CREATE ALGORITHM=UNDEFINED DEFINER=`project_tracker`@`127.0.0.1` SQL SECURITY DEFINER VIEW `user_community_roles`  AS SELECT `cm`.`user_id` AS `user_id`, `cm`.`community_id` AS `community_id`, `c`.`name` AS `community_name`, `cm`.`role` AS `role`, `cm`.`joined_at` AS `joined_at`, `cm`.`is_active` AS `is_active` FROM (`community_members` `cm` join `communities` `c` on(`cm`.`community_id` = `c`.`id`)) WHERE `cm`.`is_active` = 1 AND `c`.`is_active` = 1 ;

